def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None, db=None, imp_user=None, dehydration_hooks=None, hydration_hooks=None, **handlers):
    if not self.is_connected():
        raise ServiceUnavailable("The begin transaction is unavailable on an unconnected access")
    if self.in_transaction():
        raise TransactionError("A transaction is already in progress")

    if mode is not None:
        mode = mode.upper()
        if mode not in ("READ", "WRITE"):
            raise ValueError("Unrecognized 'mode' value")

    if bookmarks is None:
        bookmarks = []

    if metadata is None:
        metadata = {}

    if timeout is None:
        timeout = self._configuration.connection_timeout

    if db is None:
        db = self._configuration.database

    if dehydration_hooks is None:
        dehydration_hooks = self._configuration.dehydration_hooks

    if hydration_hooks is None:
        hydration_hooks = self._configuration.hydration_hooks

    command = Begin(
        self._id(),
        mode=mode,
        bookmarks=bookmarks,
        metadata=metadata,
        timeout=timeout,
        db=db,
        imp_user=imp_user,
        dehydration_hooks=dehydration_hooks,
        hydration_hooks=hydration_hooks,
    )

    self._append(command, handlers)

    return command.result

