    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Check if the function has been called with these arguments before
            if (args, kwargs) in cache:
                # If so, return the cached result
                return cache[(args, kwargs)]
            # If not, save the result of the function call for future use
            result = func(*args, **kwargs)
            cache.insert(0, (args, kwargs), result)
            # Remove the oldest result from the cache if we've reached the max size
            if len(cache) > maxsize:
                cache.pop()
            return result
        wrapper.cache = {}
        return wrapper
    return decorator

