def extostr(e, max_level=30, max_path_level=5):
    exc_type = e.__class__.__name__
    exc_msg = str(e)
    if not inspect.trace():
        return "%s: %s" % (exc_type, exc_msg)

    stack = inspect.stack()
    call_stack = []
    call_info = {}
    for frame_info in stack[1:max_level+1]:
        frame = frame_info[0]
        code = frame.f_code
        call_name = code.co_name
        filename = os.path.basename(code.co_filename)
        line = frame.f_lineno
        if call_name in call_info:
            call_info[call_name].append((filename, line))
        else:
            call_info[call_name] = [(filename, line)]
        call_stack.append((call_name, filename, line))

    for i in range(len(call_stack)):
        call_name, filename, line = call_stack[i]
        if call_name in call_info:
            call_info[call_name] = inspect.getsource(call_info[call_name])

    for call_name, source in call_info.items():
        if call_name == "get_locals":
            source = inspect.getsource(source)
        if not source:
            del call_info[call_name]

    return "%s: %s\n%s" % (exc_type, exc_msg, "\n".join(["%s: %s" % (call_name, source) for call_name, source in call_info.items()]))

