def difference(d1, d2, level=-1):
    # if d1 and d2 are the same object, return an empty dictionary
    if d1 is d2:
        return {}
    # if d2 is an empty dictionary, return d1
    if not d2:
        return d1
    # if d1 is an empty dictionary, return an empty dictionary
    if not d1:
        return {}
    # create an empty dictionary to store the difference
    diff = {}
    # iterate over the items in d1
    for key, value in d1.items():
        # if the key is not in d2, or the values are different, add it to the difference
        if key not in d2 or value != d2[key]:
            diff[key] = value
        # if the value is a dictionary, and the maximum recursion depth has not been reached,
        # subtract the values and check if the resulting dictionary is empty
        elif isinstance(value, dict) and (level != 0):
            diff[key] = difference(value, d2[key], level-1)
            if not diff[key]:
                del diff[key]
    return diff

