def _validate_labels(labels):
    # Check that keys and values in the given labels match against their corresponding
    # regular expressions.
    messages = []
    for key, value in labels.items():
        if not isinstance(key, str):
            messages.append({key: 'expected string or bytes-like object'})
        if not isinstance(value, (str, bytes)):
            messages.append({key: 'expected string or bytes-like object'})
        if re.match(r'^[a-z0-9-_.]+$', key) is None:
            messages.append({key: f"Label key '{key}' does not match the regex '[a-z0-9-_.]+'"})
    if messages:
        raise ValidationError(messages)

def _validate_labels(labels):
    errors = []
    for label_key, label_value in labels.items():
        if not isinstance(label_key, str):
            errors.append({label_key: 'expected string or bytes-like object'})
        if not isinstance(label_value, (str, bytes)):
            errors.append({label_value: 'expected string or bytes-like object'})
        if not _LABEL_KEY_REGEX.match(label_key):
            errors.append({label_key: f'Label key {label_key!r} does not match the regex {_LABEL_KEY_REGEX.pattern!r}'})
