def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if isinstance(commands, list):
        command = " ".join(commands)
    else:
        command = commands
    if cwd is not None:
        os.chdir(cwd)
    if env is not None:
        os.environ.update(env)
    process = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if verbose:
        print("Running command: {}".format(command))
    stdout, stderr = process.communicate()
    if verbose and not hide_stderr:
        print("Command output: {}".format(stdout))
    if process.returncode != 0:
        raise ProgramError("Command '{}' failed with exit code {}.".format(command, process.returncode))

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    return_code = 0
    output = None

    try:
        if isinstance(commands, str):
            commands = [commands]

        for command in commands:
            if verbose:
                print("Running command: {}".format(command))

            result = subprocess.check_output(command, cwd=cwd, shell=True, env=env,
                                             stderr=subprocess.STDOUT)

            if not hide_stderr:
                print(result.decode("utf-8"))

            return_code = result.returncode
            output = result.stdout

    except subprocess.CalledProcessError as e:
        return_code = e.returncode
        output = e.output

    return return_code, output

