                namaste_file.close()
                if 'OCFL' in namaste_content:
                    # Namaste file with OCFL keyword indicates a root directory
                    return 'root'
                elif '0=*' in namaste_content:
                    # Namaste file with 0=* indicates an object directory
                    return 'object'
                else:
                    # Other Namaste file indicates a file
                    return 'file'
        else:
            # No Namaste file found
            return 'error: no Namaste file found'
    except Exception as e:
        return 'error: ' + str(e)

