def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop(0)
        seen.add(c)

        for sc in c.__subclasses__():
            if sc not in seen:
                queue.append(sc)

    return seen.difference({cls})

