def _split_windows(s):
    # Windows command-line parsing is much more complex and there is no reliable
    # Python implementation available, so we use a simple REGEX-based parser.
    # This implementation is not perfect and has some corner cases where it may
    # not work correctly, but it should be good enough for most use cases.
    # Reference: https://msdn.microsoft.com/en-us/library/a1y7w461.aspx
    parser = re.compile(r'''
        (?:              # Group for token alternatives.
          "[^"]+"        # Either a double-quoted string without any double-quotes
        | '[^']+'        # or a single-quoted string without any single-quotes
        | [^\s"]+        # or one or more characters that is neither a space nor a double-quote
        )                # End of token alternatives group.
        (?:\s+|$)       # Followed by one or more spaces or the end of the string.
    ''', re.VERBOSE)
    return parser.findall(s)
