def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    match = re.match(r"^(\d+) (\w+)$", frequency)
    if not match:
        raise ValueError("Invalid frequency string: '{}'".format(frequency))
    amount, unit = match.groups()
    amount = int(amount)
    if unit in ["day", "days"]:
        return datetime.timedelta(days=amount)
    elif unit in ["week", "weeks"]:
        return datetime.timedelta(weeks=amount)
    elif unit in ["month", "months"]:
        return datetime.timedelta(days=30 * amount)
    elif unit in ["year", "years"]:
        return datetime.timedelta(days=365 * amount)
    else:
        raise ValueError("Invalid unit of time: '{}'".format(unit))

