def from_ticks(cls, ticks, tz=None):
    """Create a time from ticks (nanoseconds since midnight).

    Args:
        ticks (int): nanoseconds since midnight
        tz (datetime.tzinfo, optional): optional timezone

    Raises:
        ValueError: if ticks is out of bounds (0 <= ticks < 86400000000000)

    Returns:
        Time: a time object
    """
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks must be between 0 and 86400000000000")
    hour = ticks // 3600000000000
    minute = (ticks - hour * 3600000000000) // 60000000000
    second = (ticks - hour * 3600000000000 - minute * 60000000000) // 1000000000
    microsecond = (ticks - hour * 3600000000000 - minute * 60000000000 - second * 1000000000) // 1000
    if tz is not None:
        return cls(hour, minute, second, microsecond, tzinfo=tz)
    else:
        return cls(hour, minute, second, microsecond)

