    # Make sure the candidate claims to provide iface.
    if not tentative and not iface.providedBy(candidate):
        raise ValueError(f"{candidate} does not provide {iface}")

    # Get all the methods and attributes.
    valid = True
    errors = []
    for name in iface:
        # Verify all attributes.
        if name not in candidate:
            errors.append(f"{name} is not defined in {candidate}")
            valid = False
        else:
