def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError('the dic parameter should be a dictionary object')
    if not isinstance(key, str):
        raise TypeError('the key parameter should be a string object')
    if isinstance(keys, tuple):
        keys = list(keys)
    if not isinstance(keys, list):
        raise TypeError('the keys parameter should be a list object')

    current_level = dic
    for i, sub_key in enumerate(keys):
        if sub_key not in current_level:
            current_level[sub_key] = {}
        if i < len(keys) - 1:
            current_level = current_level[sub_key]
        else:
            current_level[sub_key] = val

    return dic

