def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    with open(yaml_file, 'r') as stream:
        try:
            return yaml.safe_load(stream)
        except yaml.YAMLError as exc:
            raise IRValidatorException('Failed to load & validate YAML file: {}'.format(exc))

def validate_from_file(cls, yaml_file=None):
    try:
        with open(yaml_file) as f:
            data = yaml.load(f)
    except FileNotFoundError as e:
        raise IRValidatorException("YAML file '{}' not found.".format(yaml_file))
    except NotADirectoryError as e:
        raise IRValidatorException("YAML file '{}' not a valid file.".format(yaml_file))

    required_fields = cls.get_required_fields()
    for field in required_fields:
        if field not in data:
            raise IRValidatorException("Missing required field '{}' in YAML file '{}'.".format(field, yaml_file))

    return data

