def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    for parser_key, parser_value in parser_dict.items():
        if isinstance(parser_value, dict):
            if 'include' in parser_value:
                self._include_groups(parser_value)
                parser_dict.update(parser_value)
            else:
                self._include_groups(parser_value)
        else:
            if 'include' in parser_dict[parser_key]:
                included_groups = self._include_groups(parser_dict[parser_key])
                parser_dict[parser_key] = included_groups
    return parser_dict

