def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    min_val = getattr(self, 'min_val', None)
    max_val = getattr(self, 'max_val', None)
    if min_val is not None and max_val is not None:
        if not (min_val <= args <= max_val):
            raise ValueError(
                f"{self.__class__.__name__}: value must be between {min_val} and {max_val}, got {args}")
    elif min_val is not None and max_val is None:
        if not (min_val <= args):
            raise ValueError(
                f"{self.__class__.__name__}: value must be greater than or equal to {min_val}, got {args}")
    elif min_val is None and max_val is not None:
        if not (args <= max_val):
            raise ValueError(
                f"{self.__class__.__name__}: value must be less than or equal to {max_val}, got {args}")
    return args

