def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
   """

    converter = self.application.get_converter(parser_name)
    for key, value in values_dict.items():
        convert_func = converter.get_convert_func(key)
        if convert_func is not None:
            try:
                values_dict[key] = convert_func(value)
            except ValueError:
                logger.error(f'Invalid value "{value}" for key "{key}".')
        else:
            values_dict[key] = value

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = optparse.OptionParser()
    for opt in self.option_list:
        if opt.dest == "help":
            continue
        # Use add_option only if the option is not already in the parser
        if not parser.has_option(opt.dest):
            parser.add_option(opt.dest, action="store", dest=opt.dest, type=opt.atype)

    (options, args) = parser.parse_args(values_dict)
    values_dict.update(options.__dict__)

    for opt in self.option_list:
        if opt.dest not in values_dict:
            continue
        if opt.type == "int":
            values_dict[opt.dest] = int(values_dict[opt.dest])
        elif opt.type == "float":
            values_dict[opt.dest] = float(values_dict[opt.dest])
        elif opt.type == "list":
            values_dict[opt.dest] = values_dict[opt.dest].split(",")
        elif opt.type == "bool":
            values_dict[opt.dest] = values_dict[opt.dest].lower() == "true"

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self._get_parser(parser_name)
    for arg_name, arg_value in values_dict.items():
        arg = parser.get_arg(arg_name)
        if arg is not None:
            arg_type = arg.type
            if arg_type is not None:
                try:
                    values_dict[arg_name] = arg_type(arg_value)
                except ValueError:
                    raise ValueError(f"Invalid value for argument '{arg_name}': {arg_value}")
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's directory.
    :return: A flatten dictionary contains the plugin's properties.
    """
    with open(os.path.join(plugin_dir, 'plugin.spec'), 'r') as f:
        spec = yaml.safe_load(f)
    flatten_dict = {
        key: val
        for comp in spec['components']
        for key, val in comp.items()
    }
    return flatten_dict

